namespace gem5
{

    CHAOSPTW::CHAOSPTW(const CHAOSPTWParams &p)
        : SimObject(p),
          mmu(dynamic_cast<ArmISA::MMU *>(p.mmu)),
          probability(p.probability),
          num_bits(p.bitsToChange),
          fault_mask(p.faultMask),
          byte_offset(p.byteOffset),
