        if (off < 0) {
            std::uniform_int_distribution<int> bd(0, 7);
            off = bd(rng);
        }
        if (off < 0 || off > 7) off = 7;

        Addr orig = *addr;
        // Zero byte `off` (MSB-first ordering: byte 7 = bits 56..63).
